INSERT INTO `abnormal_students` VALUES (1,6,1,'内向安静','轻度','课堂上较少主动发言，与同学互动较少，需要关注社交融入情况','ongoing','2026-04-25','2026-04-28 17:37:45','2026-04-28 17:37:45'),(2,8,1,'注意力不集中','中度','上课易走神，小动作较多，学习效率受影响','pending','2026-04-24','2026-04-28 17:37:45','2026-04-28 17:37:45'),(3,13,1,'胆小害羞','轻度','在集体活动中表现退缩，不敢表达自己的想法','ongoing','2026-04-20','2026-04-28 17:37:45','2026-04-28 17:37:45'),(4,19,1,'性格内向','轻度','长期独处，较少参与同伴游戏，需引导社交行为','closed','2026-04-18','2026-04-28 17:37:45','2026-04-28 17:37:45'),(5,28,1,'内向安静','轻度','不主动交流，喜欢独处，参与度低','ongoing','2026-04-25','2026-04-28 17:43:45','2026-04-28 17:43:45'),(6,45,10,'注意力不集中','中度','上课易分心，完成任务拖沓','pending','2026-04-24','2026-04-28 17:43:45','2026-04-28 17:47:05'),(7,67,2,'胆小害羞','轻度','害怕集体发言，不敢与人对视','ongoing','2026-04-23','2026-04-28 17:43:45','2026-04-28 17:47:05'),(8,89,9,'情绪低落','轻度','日常状态低迷，积极性差','closed','2026-04-22','2026-04-28 17:43:45','2026-04-28 17:47:05'),(9,112,6,'社交退缩','中度','拒绝参与小组活动，独处倾向明显','ongoing','2026-04-21','2026-04-28 17:43:45','2026-04-28 17:47:05'),(10,134,4,'学习焦虑','轻度','面对作业考试表现紧张','pending','2026-04-20','2026-04-28 17:43:45','2026-04-28 17:47:05'),(11,156,12,'冲动易怒','中度','容易与同学发生冲突，情绪急躁','ongoing','2026-04-19','2026-04-28 17:43:45','2026-04-28 17:47:05'),(12,178,12,'自卑敏感','轻度','对他人评价非常敏感，自信心弱','closed','2026-04-18','2026-04-28 17:43:45','2026-04-28 17:47:05'),(13,201,5,'厌学情绪','中度','对学习有抵触心理，不愿配合','ongoing','2026-04-17','2026-04-28 17:43:45','2026-04-28 17:47:05'),(14,223,5,'害怕发言','轻度','课堂从不主动回答，惧怕公开表现','pending','2026-04-16','2026-04-28 17:43:45','2026-04-28 17:47:05'),(15,245,5,'规则意识薄弱','中度','经常违反班级纪律，屡劝效果差','ongoing','2026-04-15','2026-04-28 17:43:45','2026-04-28 17:47:05'),(16,267,7,'适应困难','轻度','环境变动后难以快速融入','closed','2026-04-14','2026-04-28 17:43:45','2026-04-28 17:47:05'),(17,289,14,'拖延行为','中度','任务习惯性拖延，效率低下','ongoing','2026-04-13','2026-04-28 17:43:45','2026-04-28 17:47:05'),(18,302,8,'人际冲突','中度','与同学关系紧张，频繁闹矛盾','pending','2026-04-12','2026-04-28 17:43:45','2026-04-28 17:47:05'),(19,315,8,'过度依赖','轻度','学习生活均需要