DROP TABLE IF EXISTS `chat_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chat_history` (
  `id` int NOT NULL AUTO_INCREMENT,
  `student_id` int NOT NULL,
  `role` varchar(20) NOT NULL COMMENT 'user/assistant',
  `content` text NOT NULL,
  `grade_level` varchar(20) DEFAULT 'upper_primary',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `flag_type` varchar(20) DEFAULT NULL COMMENT '关键词命中类型: mood/bully/study/other',
  `handled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '教师是否已处理',
  `handled_by` int DEFAULT NULL COMMENT '处理教师ID',
  `handled_at` datetime DEFAULT NULL COMMENT '处理时间',
  PRIMARY KEY (`id`),
  KEY `idx_student` (`student_id`),
  KEY `idx_handled_time` (`handled`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
