DROP TABLE IF EXISTS `pets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pets` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `type` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '宠物类型(如：鱼、仓鼠、兔子等)',
  `image_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '宠物图片URL',
  `description` text COLLATE utf8mb4_general_ci COMMENT '宠物描述',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='宠物表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `pets`
--

LOCK TABLES `pets` WRITE;
/*!40000 ALTER TABLE `pets` DISABLE KEYS */;
INSERT INTO `pets` VALUES (1,'dog','/images/pets/dog1.jpg','活泼又忠诚的小狗狗，会摇着尾巴迎接主人，是校园里最暖心的小伙伴。'),(2,'cat','/images/pets/cat1.jpg','软乎乎的小猫咪，时而高冷时而粘人，是治愈不开心的小能手。'),(3,'bear','/images/pets/bear1.jpg','圆滚滚的小熊，看起来憨憨的，却是个超有安全感的守护小宝贝。'),(4,'penguin','/images/pets/penguin1.jpg','走路摇摇摆摆的小企鹅，像个穿黑礼服的小绅士，呆萌又可爱。'),(5,'bunny','/images/pets/bunny1.jpg','长耳朵软毛小兔子，蹦蹦跳跳的样子，像一团会动的棉花糖。'),(6,'bird','/images/pets/bird1.jpg','叽叽喳喳的小鸟，歌声清脆悦耳，是清晨叫醒你的小闹钟。'),(7,'hedgehog','/images/pets/hedgehog1.jpg','卷成刺球的小刺猬，虽然外表带刺，内心却软乎乎的，超害羞。'),(8,'squirrel','/images/pets/squirrel1.jpg','尾巴蓬松的小松鼠，最爱抱着坚果啃，是个勤劳的小零食收藏家。'),(9,'pup','/images/pets/pup1.jpg','奶乎乎的小奶狗，圆溜溜的大眼睛，一看就让人心都化了。'),(10,'koala','/images/pets/koala1.jpg','懒懒的小考拉，抱着树就不想撒手，慢悠悠的样子超治愈。');
/*!40000 ALTER TABLE `pets` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `picture_books`
